function sameDomain(email, domain) {
  if (!domain) return true;
  const d = String(email.split('@')[1] || '').toLowerCase();
  const base = String(domain).toLowerCase().replace(/^www\./, '');
  return d === base || d.endsWith('.' + base) || base.endsWith('.' + d);
