  ['AG', /\bAG\b/],
  ['GbR', /\bGbR\b/],
  ['e.K.', /\be\.\s?K(?:fm|fr)?\.?/],
  ['KG', /\bKG\b/],
  ['OHG', /\bOHG\b/],
  ['e.U.', /\be\.U\.?/],
